package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string = "N"
var WsLabel string = "                    "
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var partRec PartRec
var partFileScanner *bufio.Scanner
var partFileHandle *os.File
var inputDone bool

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func readRecordString(raw string, recLen int) string {
	if len(raw) < recLen {
		raw = raw + strings.Repeat(" ", recLen-len(raw))
	} else if len(raw) > recLen {
		raw = raw[:recLen]
	}
	return raw
}

func parsePartRec(line string) PartRec {
	var r PartRec
	// pad to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	}
	if len(line) > 15 {
		line = line[:15]
	}
	r.LbPart = line[0:8]
	r.LbRegion = line[8:11]
	serialStr := line[11:15]
	serialStr = strings.TrimSpace(serialStr)
	if serialStr == "" {
		r.LbSerial = 0
	} else {
		var v int64
		fmt.Sscanf(serialStr, "%d", &v)
		r.LbSerial = v
	}
	return r
}

func formatPic9(value int64, digits int) string {
	// zero padded, high-order truncated
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if digits < 19 {
		// keep low-order digits
		if value < 0 {
			value = -value
		}
		value = value % mod
	}
	s := fmt.Sprintf("%0*d", digits, value)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		// If file does not exist, treat as empty
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			inputDone = true
			MAIN_PARA()
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	partFileHandle = f
	defer f.Close()
	partFileScanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	partFileScanner.Buffer(buf, 10*1024*1024)

	MAIN_PARA()
}

func MAIN_PARA() {
	OPEN_INPUT_PART_FILE()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	CLOSE_PART_FILE()
	SUMMARY_PARA()
}

func OPEN_INPUT_PART_FILE() {
	// already opened in main; if no handle (file not found handled), nothing
}

func CLOSE_PART_FILE() {
	if partFileHandle != nil {
		partFileHandle.Close()
	}
}

func READ_PARA() {
	if partFileScanner == nil {
		WsEofFlag = "Y"
		inputDone = true
		return
	}
	if partFileScanner.Scan() {
		line := partFileScanner.Text()
		// LINE SEQUENTIAL: line without newline; pad to record length on read
		line = readRecordString(line, 15)
		partRec = parsePartRec(line)
	} else {
		WsEofFlag = "Y"
		inputDone = true
	}
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(partRec.LbPart, "A"))

	// STRING LB-REGION DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-PART DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-SERIAL DELIMITED BY SIZE
	//     INTO WS-LABEL
	part1 := delimitedBySpace(partRec.LbRegion)
	part2 := "-"
	part3 := delimitedBySpace(partRec.LbPart)
	part4 := "-"
	serialFormatted := formatPic9(partRec.LbSerial, 4)
	part5 := serialFormatted // DELIMITED BY SIZE => whole field

	concatenated := part1 + part2 + part3 + part4 + part5
	// INTO WS-LABEL: copy left to right, pad with spaces? But we blanked, and STRING does not pad beyond?
	// COBOL STRING INTO will fill and leave remainder unchanged; since we blanked, remainder stays spaces
	// Truncate if longer than 20
	if len(concatenated) > 20 {
		concatenated = concatenated[:20]
	}
	// Build WS-LABEL
	wsBytes := []byte(strings.Repeat(" ", 20))
	copy(wsBytes, []byte(concatenated))
	WsLabel = string(wsBytes)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA += WsACount
	WsTotalA = WsTotalA % 1000
	// ADD 1 TO WS-COUNT
	WsCount += 1
	WsCount = WsCount % 1000

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20), then literal, then PIC 99 zero-padded 2 digits
	displayACount := formatPic9(WsACount, 2)
	fmt.Printf("%s A=%s\n", padRight(WsLabel, 20), displayACount)

	READ_PARA()
}

func SUMMARY_PARA() {
	countStr := formatPic9(WsCount, 3)
	totalStr := formatPic9(WsTotalA, 3)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}
